from fractions import Fraction

k = int(input())
for i in range(k):
    word = input()
    x = int(input())
    if word == "sides":
        total = (x - 2) * 180
        each = Fraction(total, x)
        ext = Fraction(360, x)
        print(f"n = {x}: sum {total}, each {each}, exterior {ext}")
    else:
        e = 180 - x
        if 360 % e == 0:
            print(f"angle {x}: n = {360 // e}")
        else:
            print(f"angle {x}: none")

import math
from fractions import Fraction

def exact_sqrt(q):
    # The square root of a Fraction q > 0, in simplest exact form
    n = q.numerator * q.denominator
    k = math.isqrt(n)
    while n % (k * k) != 0:
        k = k - 1
    coef = Fraction(k, q.denominator)
    r = n // (k * k)
    if r == 1:
        return f"{coef}"
    if coef == 1:
        return f"√{r}"
    if coef.denominator == 1:
        return f"{coef}√{r}"
    return f"({coef})√{r}"

k = int(input())
for i in range(k):
    a = int(input())
    b = int(input())
    c = int(input())
    s = Fraction(a + b + c, 2)
    q = s * (s - a) * (s - b) * (s - c)
    if q < 0:
        print("no triangle")
    elif q == 0:
        print("flat")
    else:
        print(f"area {exact_sqrt(q)}")
